content.content:
// Package pipeline answers one question: understand → retrieve → decide → draft → check.
//
// The draft streams from the model, but the person only sees a sentence once the check step has
// verified it: every cited passage exists and every number in the sentence appears in a cited
// passage. So time-to-first-token is the first *verified* sentence, and an unsupported sentence
// is dropped instead of sent. That is the trade: a little first-token time for never streaming
// a claim we cannot back.
package pipeline

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"
	"time"

	"github.com/Praroop1435/Vaani/internal/governor"
	"github.com/Praroop1435/Vaani/internal/llm"
	"github.com/Praroop1435/Vaani/internal/retrieve"
)

type Config struct {
	Setting           retrieve.Setting
	Deadline          time.Duration // give-up time for the whole request
	Policy            llm.Policy
	FirstTokenTimeout time.Duration // per model call
	Understand        bool          // spend a model call to rewrite the question into a search query
	LowBudget         int           // below this many daily requests left, skip Understand
	OffTopicScore     float32       // best retrieval score under this: refuse without calling the model
	DraftMaxTokens    int
	UnderstandMax     int
}

// Defaults chosen from measurements: 0.50 sits under every answerable benchmark question's best
// score (min 0.626) and over clearly off-library questions (0.38-0.47), see Docs/RETRIEVAL_EVAL.md.
var Defaults = Config{
	Setting: retrieve.A, Deadline: 20 * time.Second, Policy: llm.DefaultPolicy,
	FirstTokenTimeout: 6 * time.Second, Understand: true, LowBudget: 100, OffTopicScore: 0.50,
	DraftMaxTokens: 700, UnderstandMax: 300,
}

type Pipeline struct {
	LLM *llm.Client
	Gov *governor.Governor
	Ret *retrieve.Retriever
	Cfg Config
}

type Step struct {
	Name      string            `json:"name"`
	WaitMs    float64           `json:"wait_ms"`  // queued behind the rate limit
	WorkMs    float64           `json:"work_ms"`  // model or tool time, failed attempts included
	RetryMs   float64           `json:"retry_ms"` // backoff between attempts
	Retries   int               `json:"retries"`
	FirstMs   int64             `json:"first_ms,omitempty"` // model's first content token, from step start
	TokensIn  int               `json:"tokens_in,omitempty"`
	TokensOut int               `json:"tokens_out,omitempty"`
	Note      string            `json:"note,omitempty"`
	Raw       string            `json:"raw,omitempty"`          // the model's full reply, before the check
	RateHdr   map[string]string `json:"rate_headers,omitempty"` // x-ratelimit-* / retry-after from the last attempt
}

type Citation struct {
	Tag     string `json:"tag"` // S1..Sk
	ChunkID string `json:"chunk_id"`
	Paper   string `json:"paper"`
	Page    string `json:"page"` // "5" or "4-5"
	Section string `json:"section"`
}

type Trace struct {
	RequestID    string     `json:"request_id"`
	Question     string     `json:"question"`
	Start        time.Time  `json:"start_time"`
	FirstTokenMs int64      `json:"first_token_ms"` // first verified sentence shown; -1 if none
	TotalMs      int64      `json:"total_ms"`
	Status       string     `json:"status"` // ok, rate_limited, timeout, error
	Refused      bool       `json:"refused"`
	Retries      int        `json:"retries"`
	TokensIn     int        `json:"tokens_in"`
	TokensOut    int        `json:"tokens_out"`
	Answer       string     `json:"answer"`
	Citations    []Citation `json:"citations"`
	Dropped      []string   `json:"dropped,omitempty"`  // sentences the check refused to send
	Degraded     []string   `json:"degraded,omitempty"` // e.g. "understand_skipped_low_budget"
	Steps        []Step     `json:"steps"`
	Err          string     `json:"error,omitempty"`
}

const refusalToken = "NOT IN PAPERS"

var shortName = map[string]string{
	"1706.03762v7": "Attention Is All You Need", "2410.00037v1": "Moshi", "2507.07955v2": "H-Net (Dynamic Chunking)",
}

// Answer runs the whole pipeline. emit receives each verified piece of the reply as soon as it
// passes the check (nil is fine).
func (p *Pipeline) Answer(ctx context.Context, reqID, question string, emit func(string)) (tr Trace) {
	tr = Trace{RequestID: reqID, Question: question, Start: time.Now(), FirstTokenMs: -1, Status: "ok"}
	ctx, cancel := context.WithTimeout(ctx, p.Cfg.Deadline)
	defer cancel()
	say := func(s string) {
		if tr.FirstTokenMs < 0 {
			tr.FirstTokenMs = time.Since(tr.Start).Milliseconds()
		}
		tr.Answer += s
		if emit != nil {
			emit(s)
		}
	}
	defer func() { tr.TotalMs = time.Since(tr.Start).Milliseconds() }()

	// 1. Understand (optional model call): rewrite the question into a search query.
	query := question
	if p.Cfg.Understand {
		if p.Gov.DailyLeft() < p.Cfg.LowBudget {
			tr.Degraded = append(tr.Degraded, "understand_skipped_low_budget")
		} else if q, st, err := p.understand(ctx, question); err != nil {
			tr.Steps = append(tr.Steps, st)
			tr.Degraded = append(tr.Degraded, "understand_failed: "+short(err))
		} else {
			tr.Steps = append(tr.Steps, st)
			query = q
		}
	}

	// 2. Retrieve (tool): search with the original question and the rewrite, keep the best.
	t0 := time.Now()
	hits, err := p.retrieve(ctx, question, query)
	tr.Steps = append(tr.Steps, Step{Name: "retrieve", WorkMs: msSince(t0), Note: fmt.Sprintf("query=%q", query)})
	if err != nil {
		return p.fail(tr, "error", err)
	}

	// 3. Decide: clearly off-library questions are refused without spending a model call.
	if len(hits) == 0 || hits[0].Score < p.Cfg.OffTopicScore {
		tr.Refused = true
		tr.Steps = append(tr.Steps, Step{Name: "decide", Note: fmt.Sprintf("refuse: best score %.3f < %.2f", top(hits), p.Cfg.OffTopicScore)})
		say("The three papers in this library (Attention Is All You Need, Moshi, H-Net) do not cover this question.")
		return tr
	}
	tr.Steps = append(tr.Steps, Step{Name: "decide", Note: fmt.Sprintf("draft: best score %.3f", hits[0].Score)})

	// 4-5. Draft (model call, streamed) and Check (tool), with one re-draft if nothing verified.
	cites := citations(hits)
	var feedback string
	for attempt := 0; attempt < 2; attempt++ {
		verified, refused, dropped, st, err := p.draftAndCheck(ctx, question, hits, cites, feedback, say)
		tr.Steps = append(tr.Steps, st)
		tr.Dropped = append(tr.Dropped, dropped...)
		if err != nil {
			if verified > 0 { // part of the answer already reached the person
				tr.Degraded = append(tr.Degraded, "answer_cut_short: "+short(err))
				return p.finishCitations(tr, cites)
			}
			p.fallback(&tr, err, hits, say)
			return p.finishCitations(tr, nil)
		}
		if refused {
			tr.Refused = true
			say("The papers do not say. The closest passages are " + listCites(cites) + ".")
			return p.finishCitations(tr, nil)
		}
		if verified > 0 {
			return p.finishCitations(tr, cites)
		}
		feedback = "Your previous reply had no sentence that followed the rules (" + strings.Join(dropped, " | ") + "). Answer again: only facts from the passages, every sentence ending with its [S#] tags, or exactly " + refusalToken + "."
		if dl, ok := ctx.Deadline(); ok && time.Until(dl) < 4*time.Second {
			break
		}
	}
	tr.Refused = true
	say("I could not write an answer that the papers support. The closest passages are " + listCites(cites) + ".")
	return p.finishCitations(tr, nil)
}

func (p *Pipeline) understand(ctx context.Context, question string) (string, Step, error) {
	msgs := []llm.Message{
		{Role: "system", Content: "Rewrite the user's question as one short search query for a library of three papers: " +
			"'Attention Is All You Need' (the Transformer), 'Moshi' (speech-text dialogue model; its audio codec is Mimi, its text LLM is Helium), " +
			"and 'Dynamic Chunking for End-to-End Hierarchical Sequence Modeling' (H-Net). Expand abbreviations and name the model or component. " +
			"Reply with the query only, on one line."},
		{Role: "user", Content: question},
	}
	res, st, err := p.call(ctx, "understand", msgs, p.Cfg.UnderstandMax, nil)
	q := strings.TrimSpace(strings.SplitN(res.Text, "\n", 2)[0])
	if err == nil && q == "" {
		err = errors.New("empty rewrite")
	}
	return q, st, err
}

func (p *Pipeline) retrieve(ctx context.Context, question, query string) ([]retrieve.Hit, error) {
	res, err := p.Ret.Retrieve(ctx, question, p.Cfg.Setting)
	if err != nil || query == question {
		return res.Hits, err
	}
	res2, err := p.Ret.Retrieve(ctx, query, p.Cfg.Setting)
	if err != nil {
		return res.Hits, nil
	}
	best := map[string]retrieve.Hit{}
	for _, h := range append(res.Hits, res2.Hits...) {
		if b, ok := best[h.Chunk.ID]; !ok || h.Score > b.Score {
			best[h.Chunk.ID] = h
		}
	}
	var merged []retrieve.Hit
	for _, h := range best {
		merged = append(merged, h)
	}
	slices.SortFunc(merged, func(a, b retrieve.Hit) int {
		if a.Score != b.Score {
			if a.Score > b.Score {
				return -1
			}
			return 1
		}
		return strings.Compare(a.Chunk.ID, b.Chunk.ID)
	})
	return merged[:min(p.Cfg.Setting.K, len(merged))], nil
}

// call reserves budget, then runs the model call under the retry policy, and records the step.
func (p *Pipeline) call(ctx context.Context, name string, msgs []llm.Message, maxTok int, onTok func(string)) (llm.Result, Step, error) {
	st := Step{Name: name}
	chars := 0
	for _, m := range msgs {
		chars += len(m.Content)
	}
	est := chars/4 + maxTok // Groq counts reserved completion tokens against the per-minute limit
	t0 := time.Now()
	waited, err := p.Gov.Reserve(ctx, est)
	st.WaitMs = float64(waited.Microseconds()) / 1000
	if err != nil {
		st.Note = "reserve: " + err.Error()
		st.WaitMs = msSince(t0)
		return llm.Result{}, st, err
	}
	var first int64 = -1
	start := time.Now()
	res, stats, err := llm.Do(ctx, p.Cfg.Policy, func(actx context.Context) (llm.Result, error) {
		r, err := p.LLM.ChatStream(actx, msgs, llm.Options{MaxTokens: maxTok, FirstTokenTimeout: p.Cfg.FirstTokenTimeout, OnToken: func(s string) {
			if first < 0 {
				first = time.Since(start).Milliseconds()
			}
			if onTok != nil {
				onTok(s)
			}
		}})
		p.Gov.Observe(r.Header)
		return r, err
	})
	st.WorkMs, st.RetryMs, st.Retries = stats.WorkMs, stats.RetryWaitMs, stats.Retries()
	st.FirstMs, st.TokensIn, st.TokensOut = first, res.TokensIn, res.TokensOut
	st.Raw = res.Text
	for k, v := range res.Header {
		if k = strings.ToLower(k); strings.HasPrefix(k, "x-ratelimit-") || k == "retry-after" {
			if st.RateHdr == nil {
				st.RateHdr = map[string]string{}
			}
			st.RateHdr[k] = strings.Join(v, ",")
		}
	}
	if err != nil {
		st.Note = short(err)
	}
	return res, st, err
}

var (
	tagGroup = regexp.MustCompile(`(?:\s*\[S\d+\])+[.!?]?`)
	tagRe    = regexp.MustCompile(`\[(S\d+)\]`)
	numRe    = regexp.MustCompile(`\d+(?:[.,]\d+)*`)
)

// draftAndCheck streams the draft and releases each sentence group (text up to and including its
// [S#] tags) only after it passes the check. Untagged text waits for the next tag group.
func (p *Pipeline) draftAndCheck(ctx context.Context, question string, hits []retrieve.Hit, cites map[string]Citation, feedback string, say func(string)) (verified int, refused bool, dropped []string, st Step, err error) {
	var b strings.Builder
	for i, h := range hits {
		c := cites[fmt.Sprintf("S%d", i+1)]
		fmt.Fprintf(&b, "[S%d] (%s, page %s, section %s)\n%s\n\n", i+1, shortName[c.Paper], c.Page, c.Section, h.Chunk.Text)
	}
	msgs := []llm.Message{
		{Role: "system", Content: "You answer engineers' questions using ONLY the numbered passages from three research papers.\n" +
			"Rules:\n1. Use only facts stated in the passages. No outside knowledge.\n" +
			"2. End every sentence with the tags of the passages it relies on, e.g. \"... 8 heads [S1].\"\n" +
			"3. If the passages do not contain the answer, reply with exactly: " + refusalToken + "\n" +
			"4. At most 4 sentences. No preamble, no headings."},
		{Role: "user", Content: b.String() + "Question: " + question},
	}
	if feedback != "" {
		msgs = append(msgs, llm.Message{Role: "user", Content: feedback})
	}
	var buf string
	check := func(unit string) {
		u := strings.TrimSpace(unit)
		if u == "" {
			return
		}
		if strings.Contains(u, refusalToken) {
			refused = true
			return
		}
		if ok, why := verify(u, hits, cites); ok {
			if verified > 0 {
				say(" ")
			}
			say(render(u, cites))
			verified++
		} else {
			dropped = append(dropped, why+": "+u)
		}
	}
	res, st, err := p.call(ctx, "draft", msgs, p.Cfg.DraftMaxTokens, func(s string) {
		buf += s
		for {
			loc := tagGroup.FindStringIndex(buf)
			if loc == nil || loc[1] == len(buf) { // more tags or the full stop may still be coming
				return
			}
			check(buf[:loc[1]])
			buf = buf[loc[1]:]
		}
	})
	if err == nil {
		check(buf) // leftover after the last tag group
	}
	refused = verified == 0 && strings.Contains(res.Text, refusalToken) // a verified answer beats a stray refusal
	return verified, refused, dropped, st, err
}

// verify is the check step: tags must name real passages, and every number must appear in one.
func verify(unit string, hits []retrieve.Hit, cites map[string]Citation) (bool, string) {
	tags := tagRe.FindAllStringSubmatch(unit, -1)
	if len(tags) == 0 {
		return false, "no citation"
	}
	var cited []string
	for _, t := range tags {
		c, ok := cites[t[1]]
		if !ok {
			return false, "cites missing passage " + t[1]
		}
		for _, h := range hits {
			if h.Chunk.ID == c.ChunkID { // the passage header (section, page) may be quoted too
				cited = append(cited, strings.ReplaceAll(c.Section+" page "+c.Page+" "+h.Chunk.Text, ",", ""))
			}
		}
	}
	body := tagRe.ReplaceAllString(unit, "")
	for _, n := range numRe.FindAllString(body, -1) {
		n = strings.TrimRight(strings.ReplaceAll(n, ",", ""), ".")
		re := regexp.MustCompile(`(^|[^\d.])` + regexp.QuoteMeta(n) + `([^\d]|$)`)
		if !slices.ContainsFunc(cited, re.MatchString) {
			return false, "number " + n + " not in cited passages"
		}
	}
	return true, ""
}

func render(unit string, cites map[string]Citation) string {
	return tagRe.ReplaceAllStringFunc(unit, func(t string) string {
		c := cites[t[1:len(t)-1]]
		return fmt.Sprintf("[%s, p.%s]", shortName[c.Paper], c.Page)
	})
}

func citations(hits []retrieve.Hit) map[string]Citation {
	m := map[string]Citation{}
	for i, h := range hits {
		page := fmt.Sprint(h.Chunk.PageStart)
		if h.Chunk.PageEnd != h.Chunk.PageStart {
			page = fmt.Sprintf("%d-%d", h.Chunk.PageStart, h.Chunk.PageEnd)
		}
		sec := strings.TrimSpace(h.Chunk.SectionNumber + " " + h.Chunk.Section)
		if h.Chunk.Table != "" {
			sec += " (" + h.Chunk.Table + ")"
		}
		tag := fmt.Sprintf("S%d", i+1)
		m[tag] = Citation{Tag: tag, ChunkID: h.Chunk.ID, Paper: h.Chunk.Paper, Page: page, Section: sec}
	}
	return m
}

func listCites(cites map[string]Citation) string {
	var out []string
	for i := 1; i <= len(cites); i++ {
		c := cites[fmt.Sprintf("S%d", i)]
		out = append(out, fmt.Sprintf("%s p.%s (§%s)", shortName[c.Paper], c.Page, c.Section))
	}
	return strings.Join(out, "; ")
}

func (p *Pipeline) finishCitations(tr Trace, cites map[string]Citation) Trace {
	used := map[string]bool{}
	for _, m := range regexp.MustCompile(`\[([^\]]+), p\.([\d-]+)\]`).FindAllStringSubmatch(tr.Answer, -1) {
		used[m[1]+"|"+m[2]] = true
	}
	for i := 1; i <= len(cites); i++ {
		c := cites[fmt.Sprintf("S%d", i)]
		if used[shortName[c.Paper]+"|"+c.Page] {
			tr.Citations = append(tr.Citations, c)
		}
	}
	for _, s := range tr.Steps {
		tr.Retries += s.Retries
		tr.TokensIn += s.TokensIn
		tr.TokensOut += s.TokensOut
	}
	return tr
}

// fallback answers without the model when it cannot be reached in time or within budget:
// the person gets the most relevant passages with page references, never a guessed answer.
func (p *Pipeline) fallback(tr *Trace, err error, hits []retrieve.Hit, say func(string)) {
	cites := citations(hits)
	switch {
	case errors.Is(err, governor.ErrDailyBudget) || llm.IsDaily(err):
		tr.Status = "rate_limited"
		when := "tomorrow"
		if r := p.Gov.DailyReset(); !r.IsZero() {
			when = "at " + r.Local().Format("15:04")
		}
		say("Today's model budget is used up, so I can't write an answer now; it refills " + when + ". The passages most likely to answer this are: " + listCites(cites) + ".")
	case errors.Is(err, governor.ErrDeadlineWait):
		tr.Status = "rate_limited"
		say("The assistant is at its per-minute limit and could not answer within " + p.Cfg.Deadline.String() + ". The passages most likely to answer this are: " + listCites(cites) + ". Please ask again in a minute.")
	case errors.Is(err, context.DeadlineExceeded) || errors.Is(err, llm.ErrFirstTokenTimeout):
		tr.Status = "timeout"
		say("The model did not answer in time. The passages most likely to answer this are: " + listCites(cites) + ".")
	default:
		tr.Status = "error"
		say("The model service failed. The passages most likely to answer this are: " + listCites(cites) + ".")
	}
	tr.Err = err.Error()
	tr.Degraded = append(tr.Degraded, "passages_only")
}

func (p *Pipeline) fail(tr Trace, status string, err error) Trace {
	tr.Status, tr.Err = status, err.Error()
	return tr
}

func top(h []retrieve.Hit) float32 {
	if len(h) == 0 {
		return 0
	}
	return h[0].Score
}

func msSince(t time.Time) float64 { return float64(time.Since(t).Microseconds()) / 1000 }

func short(err error) string {
	s := err.Error()
	if len(s) > 120 {
		s = s[:120]
	}
	return s
}
// Package retrieve is the pipeline's search tool: BGE cosine top-k over the chunk index.
// Brute force: ~400 vectors x 768 dims is well under a millisecond, so no vector DB.
package retrieve

import (
	"context"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"time"

	"github.com/Praroop1435/Vaani/internal/embed"
	"github.com/Praroop1435/Vaani/internal/ingest"
)

// Setting is one retrieval configuration compared in Table 3 of the write-up.
type Setting struct {
	Name      string
	ChunkSize int // which index: data/index/chunks_<size>.json
	K         int
	Windows   bool // small-to-big: search sentence windows, return their parent chunks
}

var (
	A = Setting{Name: "A: 300 tok, k=4", ChunkSize: 300, K: 4}
	B = Setting{Name: "B: 480 tok, k=3", ChunkSize: 480, K: 3}
	C = Setting{Name: "C: 2-sentence windows -> 300 tok parents, k=4", ChunkSize: 300, K: 4, Windows: true}
)

type Index struct {
	Chunks []ingest.Chunk
	Vecs   [][]float32 // unit length, same order as Chunks
	// Optional small-to-big layer: windows_<size>.json/.f32. WinParent[i] indexes Chunks.
	WinParent []int
	WinVecs   [][]float32
}

// Load reads chunks_<size>.json and vectors_<size>.f32 written by cmd/ingest.
func Load(dir string, size int) (*Index, error) {
	js, err := os.ReadFile(fmt.Sprintf("%s/chunks_%d.json", dir, size))
	if err != nil {
		return nil, err
	}
	var chunks []ingest.Chunk
	if err := json.Unmarshal(js, &chunks); err != nil {
		return nil, err
	}
	vecs, err := readVectors(fmt.Sprintf("%s/vectors_%d.f32", dir, size), len(chunks))
	if err != nil {
		return nil, err
	}
	ix := &Index{Chunks: chunks, Vecs: vecs}
	if wjs, err := os.ReadFile(fmt.Sprintf("%s/windows_%d.json", dir, size)); err == nil {
		var ws []ingest.Window
		if err := json.Unmarshal(wjs, &ws); err != nil {
			return nil, err
		}
		if ix.WinVecs, err = readVectors(fmt.Sprintf("%s/windows_%d.f32", dir, size), len(ws)); err != nil {
			return nil, err
		}
		for _, w := range ws {
			if w.Parent < 0 || w.Parent >= len(chunks) {
				return nil, fmt.Errorf("retrieve: window parent %d out of range: re-run cmd/ingest", w.Parent)
			}
			ix.WinParent = append(ix.WinParent, w.Parent)
		}
	}
	return ix, nil
}

func readVectors(path string, n int) ([][]float32, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if want := n * embed.Dim * 4; len(raw) != want {
		return nil, fmt.Errorf("retrieve: %s has %d bytes, want %d for %d rows: re-run cmd/ingest", path, len(raw), want, n)
	}
	flat := make([]float32, n*embed.Dim)
	if _, err := binary.Decode(raw, binary.LittleEndian, flat); err != nil {
		return nil, err
	}
	vecs := make([][]float32, n)
	for i := range vecs {
		vecs[i] = flat[i*embed.Dim : (i+1)*embed.Dim]
	}
	return vecs, nil
}

type Hit struct {
	Chunk ingest.Chunk
	Score float32 // cosine similarity
}

// Search returns the k chunks most similar to q, best first.
func (ix *Index) Search(q []float32, k int) []Hit {
	hits := make([]Hit, len(ix.Chunks))
	for i, v := range ix.Vecs {
		hits[i] = Hit{ix.Chunks[i], embed.Cosine(q, v)}
	}
	sort.SliceStable(hits, func(a, b int) bool { return hits[a].Score > hits[b].Score })
	return hits[:min(k, len(hits))]
}

// SearchWindows ranks windows, keeps each parent chunk's best window score, and returns the
// top k parents. The model still sees whole chunks, so tokens per answer match setting A.
func (ix *Index) SearchWindows(q []float32, k int) []Hit {
	best := map[int]float32{}
	for i, v := range ix.WinVecs {
		p, s := ix.WinParent[i], embed.Cosine(q, v)
		if cur, ok := best[p]; !ok || s > cur {
			best[p] = s
		}
	}
	hits := make([]Hit, 0, len(best))
	for p, s := range best {
		hits = append(hits, Hit{ix.Chunks[p], s})
	}
	sort.SliceStable(hits, func(a, b int) bool {
		if hits[a].Score != hits[b].Score {
			return hits[a].Score > hits[b].Score
		}
		return hits[a].Chunk.ID < hits[b].Chunk.ID // map order is random: keep ties stable
	})
	return hits[:min(k, len(hits))]
}

// Result is what the pipeline gets back from the retrieve tool, with timings for the trace.
type Result struct {
	Hits     []Hit
	EmbedMs  float64
	SearchMs float64
}

type Retriever struct {
	Embedder *embed.Embedder
	Indexes  map[int]*Index // by chunk size
}

// Retrieve embeds the question (with BGE's query prefix) and searches the setting's index.
func (r *Retriever) Retrieve(ctx context.Context, question string, s Setting) (Result, error) {
	ix := r.Indexes[s.ChunkSize]
	if ix == nil {
		return Result{}, fmt.Errorf("retrieve: no index loaded for chunk size %d", s.ChunkSize)
	}
	t0 := time.Now()
	qv, err := r.Embedder.Embed(ctx, []string{embed.QueryPrefix + question})
	if err != nil {
		return Result{}, err
	}
	t1 := time.Now()
	var hits []Hit
	if s.Windows {
		if len(ix.WinVecs) == 0 {
			return Result{}, fmt.Errorf("retrieve: setting %q needs windows_%d.* (run cmd/ingest -windows-only)", s.Name, s.ChunkSize)
		}
		hits = ix.SearchWindows(qv[0], s.K)
	} else {
		hits = ix.Search(qv[0], s.K)
	}
	return Result{
		Hits:     hits,
		EmbedMs:  float64(t1.Sub(t0).Microseconds()) / 1000,
		SearchMs: float64(time.Since(t1).Microseconds()) / 1000,
	}, nil
}
// Command ask answers one question through the full pipeline and prints the reply as it is
// verified, then the trace (steps with waiting / working / retrying time) as JSON.
// Spends 1-3 real Groq requests unless -base points at the stand-in.
//
//	go run -tags ORT ./cmd/ask "How many attention heads does the base Transformer use?"
//	go run -tags ORT ./cmd/ask -setting C -no-understand "..."
package main

import (
	"bufio"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/Praroop1435/Vaani/internal/embed"
	"github.com/Praroop1435/Vaani/internal/governor"
	"github.com/Praroop1435/Vaani/internal/llm"
	"github.com/Praroop1435/Vaani/internal/pipeline"
	"github.com/Praroop1435/Vaani/internal/retrieve"
)

func main() {
	base := flag.String("base", llm.GroqBaseURL, "OpenAI-style endpoint (Groq, or the stand-in)")
	model := flag.String("model", "openai/gpt-oss-120b", "model id")
	setting := flag.String("setting", "A", "retrieval setting: A, B or C")
	noUnderstand := flag.Bool("no-understand", false, "skip the query-rewrite model call")
	flag.Parse()
	question := strings.Join(flag.Args(), " ")
	if question == "" {
		log.Fatal("usage: ask [flags] <question>")
	}
	key := os.Getenv("GROQ_API_KEY")
	if key == "" {
		key = envFile(".env", "GROQ_API_KEY")
	}

	ctx := context.Background()
	e, err := embed.New(ctx, embed.DefaultModelDir)
	if err != nil {
		log.Fatal(err)
	}
	defer e.Close()
	s := map[string]retrieve.Setting{"A": retrieve.A, "B": retrieve.B, "C": retrieve.C}[*setting]
	ix, err := retrieve.Load("data/index", s.ChunkSize)
	if err != nil {
		log.Fatal(err)
	}
	cfg := pipeline.Defaults
	cfg.Setting, cfg.Understand = s, !*noUnderstand
	p := &pipeline.Pipeline{
		LLM: &llm.Client{BaseURL: *base, APIKey: key, Model: *model},
		Gov: governor.New(governor.Limits{RPM: 30, TPM: 8000, RPD: 1000}), // Groq free tier, gpt-oss-120b (docs, 2026-11-09)
		Ret: &retrieve.Retriever{Embedder: e, Indexes: map[int]*retrieve.Index{s.ChunkSize: ix}},
		Cfg: cfg,
	}
	tr := p.Answer(ctx, "ask-1", question, func(piece string) { fmt.Print(piece) })
	fmt.Println()
	js, _ := json.MarshalIndent(tr, "", "  ")
	fmt.Fprintln(os.Stderr, string(js))
}

func envFile(path, name string) string {
	f, err := os.Open(path)
	if err != nil {
		return ""
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		if v, ok := strings.CutPrefix(strings.TrimSpace(sc.Text()), name+"="); ok {
			return strings.Trim(v, `"'`)
		}
	}
	return ""
}

toolUseResult.stdout:
// Package pipeline answers one question: understand → retrieve → decide → draft → check.
//
// The draft streams from the model, but the person only sees a sentence once the check step has
// verified it: every cited passage exists and every number in the sentence appears in a cited
// passage. So time-to-first-token is the first *verified* sentence, and an unsupported sentence
// is dropped instead of sent. That is the trade: a little first-token time for never streaming
// a claim we cannot back.
package pipeline

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"
	"time"

	"github.com/Praroop1435/Vaani/internal/governor"
	"github.com/Praroop1435/Vaani/internal/llm"
	"github.com/Praroop1435/Vaani/internal/retrieve"
)

type Config struct {
	Setting           retrieve.Setting
	Deadline          time.Duration // give-up time for the whole request
	Policy            llm.Policy
	FirstTokenTimeout time.Duration // per model call
	Understand        bool          // spend a model call to rewrite the question into a search query
	LowBudget         int           // below this many daily requests left, skip Understand
	OffTopicScore     float32       // best retrieval score under this: refuse without calling the model
	DraftMaxTokens    int
	UnderstandMax     int
}

// Defaults chosen from measurements: 0.50 sits under every answerable benchmark question's best
// score (min 0.626) and over clearly off-library questions (0.38-0.47), see Docs/RETRIEVAL_EVAL.md.
var Defaults = Config{
	Setting: retrieve.A, Deadline: 20 * time.Second, Policy: llm.DefaultPolicy,
	FirstTokenTimeout: 6 * time.Second, Understand: true, LowBudget: 100, OffTopicScore: 0.50,
	DraftMaxTokens: 700, UnderstandMax: 300,
}

type Pipeline struct {
	LLM *llm.Client
	Gov *governor.Governor
	Ret *retrieve.Retriever
	Cfg Config
}

type Step struct {
	Name      string            `json:"name"`
	WaitMs    float64           `json:"wait_ms"`  // queued behind the rate limit
	WorkMs    float64           `json:"work_ms"`  // model or tool time, failed attempts included
	RetryMs   float64           `json:"retry_ms"` // backoff between attempts
	Retries   int               `json:"retries"`
	FirstMs   int64             `json:"first_ms,omitempty"` // model's first content token, from step start
	TokensIn  int               `json:"tokens_in,omitempty"`
	TokensOut int               `json:"tokens_out,omitempty"`
	Note      string            `json:"note,omitempty"`
	Raw       string            `json:"raw,omitempty"`          // the model's full reply, before the check
	RateHdr   map[string]string `json:"rate_headers,omitempty"` // x-ratelimit-* / retry-after from the last attempt
}

type Citation struct {
	Tag     string `json:"tag"` // S1..Sk
	ChunkID string `json:"chunk_id"`
	Paper   string `json:"paper"`
	Page    string `json:"page"` // "5" or "4-5"
	Section string `json:"section"`
}

type Trace struct {
	RequestID    string     `json:"request_id"`
	Question     string     `json:"question"`
	Start        time.Time  `json:"start_time"`
	FirstTokenMs int64      `json:"first_token_ms"` // first verified sentence shown; -1 if none
	TotalMs      int64      `json:"total_ms"`
	Status       string     `json:"status"` // ok, rate_limited, timeout, error
	Refused      bool       `json:"refused"`
	Retries      int        `json:"retries"`
	TokensIn     int        `json:"tokens_in"`
	TokensOut    int        `json:"tokens_out"`
	Answer       string     `json:"answer"`
	Citations    []Citation `json:"citations"`
	Dropped      []string   `json:"dropped,omitempty"`  // sentences the check refused to send
	Degraded     []string   `json:"degraded,omitempty"` // e.g. "understand_skipped_low_budget"
	Steps        []Step     `json:"steps"`
	Err          string     `json:"error,omitempty"`
}

const refusalToken = "NOT IN PAPERS"

var shortName = map[string]string{
	"1706.03762v7": "Attention Is All You Need", "2410.00037v1": "Moshi", "2507.07955v2": "H-Net (Dynamic Chunking)",
}

// Answer runs the whole pipeline. emit receives each verified piece of the reply as soon as it
// passes the check (nil is fine).
func (p *Pipeline) Answer(ctx context.Context, reqID, question string, emit func(string)) (tr Trace) {
	tr = Trace{RequestID: reqID, Question: question, Start: time.Now(), FirstTokenMs: -1, Status: "ok"}
	ctx, cancel := context.WithTimeout(ctx, p.Cfg.Deadline)
	defer cancel()
	say := func(s string) {
		if tr.FirstTokenMs < 0 {
			tr.FirstTokenMs = time.Since(tr.Start).Milliseconds()
		}
		tr.Answer += s
		if emit != nil {
			emit(s)
		}
	}
	defer func() { tr.TotalMs = time.Since(tr.Start).Milliseconds() }()

	// 1. Understand (optional model call): rewrite the question into a search query.
	query := question
	if p.Cfg.Understand {
		if p.Gov.DailyLeft() < p.Cfg.LowBudget {
			tr.Degraded = append(tr.Degraded, "understand_skipped_low_budget")
		} else if q, st, err := p.understand(ctx, question); err != nil {
			tr.Steps = append(tr.Steps, st)
			tr.Degraded = append(tr.Degraded, "understand_failed: "+short(err))
		} else {
			tr.Steps = append(tr.Steps, st)
			query = q
		}
	}

	// 2. Retrieve (tool): search with the original question and the rewrite, keep the best.
	t0 := time.Now()
	hits, err := p.retrieve(ctx, question, query)
	tr.Steps = append(tr.Steps, Step{Name: "retrieve", WorkMs: msSince(t0), Note: fmt.Sprintf("query=%q", query)})
	if err != nil {
		return p.fail(tr, "error", err)
	}

	// 3. Decide: clearly off-library questions are refused without spending a model call.
	if len(hits) == 0 || hits[0].Score < p.Cfg.OffTopicScore {
		tr.Refused = true
		tr.Steps = append(tr.Steps, Step{Name: "decide", Note: fmt.Sprintf("refuse: best score %.3f < %.2f", top(hits), p.Cfg.OffTopicScore)})
		say("The three papers in this library (Attention Is All You Need, Moshi, H-Net) do not cover this question.")
		return tr
	}
	tr.Steps = append(tr.Steps, Step{Name: "decide", Note: fmt.Sprintf("draft: best score %.3f", hits[0].Score)})

	// 4-5. Draft (model call, streamed) and Check (tool), with one re-draft if nothing verified.
	cites := citations(hits)
	var feedback string
	for attempt := 0; attempt < 2; attempt++ {
		verified, refused, dropped, st, err := p.draftAndCheck(ctx, question, hits, cites, feedback, say)
		tr.Steps = append(tr.Steps, st)
		tr.Dropped = append(tr.Dropped, dropped...)
		if err != nil {
			if verified > 0 { // part of the answer already reached the person
				tr.Degraded = append(tr.Degraded, "answer_cut_short: "+short(err))
				return p.finishCitations(tr, cites)
			}
			p.fallback(&tr, err, hits, say)
			return p.finishCitations(tr, nil)
		}
		if refused {
			tr.Refused = true
			say("The papers do not say. The closest passages are " + listCites(cites) + ".")
			return p.finishCitations(tr, nil)
		}
		if verified > 0 {
			return p.finishCitations(tr, cites)
		}
		feedback = "Your previous reply had no sentence that followed the rules (" + strings.Join(dropped, " | ") + "). Answer again: only facts from the passages, every sentence ending with its [S#] tags, or exactly " + refusalToken + "."
		if dl, ok := ctx.Deadline(); ok && time.Until(dl) < 4*time.Second {
			break
		}
	}
	tr.Refused = true
	say("I could not write an answer that the papers support. The closest passages are " + listCites(cites) + ".")
	return p.finishCitations(tr, nil)
}

func (p *Pipeline) understand(ctx context.Context, question string) (string, Step, error) {
	msgs := []llm.Message{
		{Role: "system", Content: "Rewrite the user's question as one short search query for a library of three papers: " +
			"'Attention Is All You Need' (the Transformer), 'Moshi' (speech-text dialogue model; its audio codec is Mimi, its text LLM is Helium), " +
			"and 'Dynamic Chunking for End-to-End Hierarchical Sequence Modeling' (H-Net). Expand abbreviations and name the model or component. " +
			"Reply with the query only, on one line."},
		{Role: "user", Content: question},
	}
	res, st, err := p.call(ctx, "understand", msgs, p.Cfg.UnderstandMax, nil)
	q := strings.TrimSpace(strings.SplitN(res.Text, "\n", 2)[0])
	if err == nil && q == "" {
		err = errors.New("empty rewrite")
	}
	return q, st, err
}

func (p *Pipeline) retrieve(ctx context.Context, question, query string) ([]retrieve.Hit, error) {
	res, err := p.Ret.Retrieve(ctx, question, p.Cfg.Setting)
	if err != nil || query == question {
		return res.Hits, err
	}
	res2, err := p.Ret.Retrieve(ctx, query, p.Cfg.Setting)
	if err != nil {
		return res.Hits, nil
	}
	best := map[string]retrieve.Hit{}
	for _, h := range append(res.Hits, res2.Hits...) {
		if b, ok := best[h.Chunk.ID]; !ok || h.Score > b.Score {
			best[h.Chunk.ID] = h
		}
	}
	var merged []retrieve.Hit
	for _, h := range best {
		merged = append(merged, h)
	}
	slices.SortFunc(merged, func(a, b retrieve.Hit) int {
		if a.Score != b.Score {
			if a.Score > b.Score {
				return -1
			}
			return 1
		}
		return strings.Compare(a.Chunk.ID, b.Chunk.ID)
	})
	return merged[:min(p.Cfg.Setting.K, len(merged))], nil
}

// call reserves budget, then runs the model call under the retry policy, and records the step.
func (p *Pipeline) call(ctx context.Context, name string, msgs []llm.Message, maxTok int, onTok func(string)) (llm.Result, Step, error) {
	st := Step{Name: name}
	chars := 0
	for _, m := range msgs {
		chars += len(m.Content)
	}
	est := chars/4 + maxTok // Groq counts reserved completion tokens against the per-minute limit
	t0 := time.Now()
	waited, err := p.Gov.Reserve(ctx, est)
	st.WaitMs = float64(waited.Microseconds()) / 1000
	if err != nil {
		st.Note = "reserve: " + err.Error()
		st.WaitMs = msSince(t0)
		return llm.Result{}, st, err
	}
	var first int64 = -1
	start := time.Now()
	res, stats, err := llm.Do(ctx, p.Cfg.Policy, func(actx context.Context) (llm.Result, error) {
		r, err := p.LLM.ChatStream(actx, msgs, llm.Options{MaxTokens: maxTok, FirstTokenTimeout: p.Cfg.FirstTokenTimeout, OnToken: func(s string) {
			if first < 0 {
				first = time.Since(start).Milliseconds()
			}
			if onTok != nil {
				onTok(s)
			}
		}})
		p.Gov.Observe(r.Header)
		return r, err
	})
	st.WorkMs, st.RetryMs, st.Retries = stats.WorkMs, stats.RetryWaitMs, stats.Retries()
	st.FirstMs, st.TokensIn, st.TokensOut = first, res.TokensIn, res.TokensOut
	st.Raw = res.Text
	for k, v := range res.Header {
		if k = strings.ToLower(k); strings.HasPrefix(k, "x-ratelimit-") || k == "retry-after" {
			if st.RateHdr == nil {
				st.RateHdr = map[string]string{}
			}
			st.RateHdr[k] = strings.Join(v, ",")
		}
	}
	if err != nil {
		st.Note = short(err)
	}
	return res, st, err
}

var (
	tagGroup = regexp.MustCompile(`(?:\s*\[S\d+\])+[.!?]?`)
	tagRe    = regexp.MustCompile(`\[(S\d+)\]`)
	numRe    = regexp.MustCompile(`\d+(?:[.,]\d+)*`)
)

// draftAndCheck streams the draft and releases each sentence group (text up to and including its
// [S#] tags) only after it passes the check. Untagged text waits for the next tag group.
func (p *Pipeline) draftAndCheck(ctx context.Context, question string, hits []retrieve.Hit, cites map[string]Citation, feedback string, say func(string)) (verified int, refused bool, dropped []string, st Step, err error) {
	var b strings.Builder
	for i, h := range hits {
		c := cites[fmt.Sprintf("S%d", i+1)]
		fmt.Fprintf(&b, "[S%d] (%s, page %s, section %s)\n%s\n\n", i+1, shortName[c.Paper], c.Page, c.Section, h.Chunk.Text)
	}
	msgs := []llm.Message{
		{Role: "system", Content: "You answer engineers' questions using ONLY the numbered passages from three research papers.\n" +
			"Rules:\n1. Use only facts stated in the passages. No outside knowledge.\n" +
			"2. End every sentence with the tags of the passages it relies on, e.g. \"... 8 heads [S1].\"\n" +
			"3. If the passages do not contain the answer, reply with exactly: " + refusalToken + "\n" +
			"4. At most 4 sentences. No preamble, no headings."},
		{Role: "user", Content: b.String() + "Question: " + question},
	}
	if feedback != "" {
		msgs = append(msgs, llm.Message{Role: "user", Content: feedback})
	}
	var buf string
	check := func(unit string) {
		u := strings.TrimSpace(unit)
		if u == "" {
			return
		}
		if strings.Contains(u, refusalToken) {
			refused = true
			return
		}
		if ok, why := verify(u, hits, cites); ok {
			if verified > 0 {
				say(" ")
			}
			say(render(u, cites))
			verified++
		} else {
			dropped = append(dropped, why+": "+u)
		}
	}
	res, st, err := p.call(ctx, "draft", msgs, p.Cfg.DraftMaxTokens, func(s string) {
		buf += s
		for {
			loc := tagGroup.FindStringIndex(buf)
			if loc == nil || loc[1] == len(buf) { // more tags or the full stop may still be coming
				return
			}
			check(buf[:loc[1]])
			buf = buf[loc[1]:]
		}
	})
	if err == nil {
		check(buf) // leftover after the last tag group
	}
	refused = verified == 0 && strings.Contains(res.Text, refusalToken) // a verified answer beats a stray refusal
	return verified, refused, dropped, st, err
}

// verify is the check step: tags must name real passages, and every number must appear in one.
func verify(unit string, hits []retrieve.Hit, cites map[string]Citation) (bool, string) {
	tags := tagRe.FindAllStringSubmatch(unit, -1)
	if len(tags) == 0 {
		return false, "no citation"
	}
	var cited []string
	for _, t := range tags {
		c, ok := cites[t[1]]
		if !ok {
			return false, "cites missing passage " + t[1]
		}
		for _, h := range hits {
			if h.Chunk.ID == c.ChunkID { // the passage header (section, page) may be quoted too
				cited = append(cited, strings.ReplaceAll(c.Section+" page "+c.Page+" "+h.Chunk.Text, ",", ""))
			}
		}
	}
	body := tagRe.ReplaceAllString(unit, "")
	for _, n := range numRe.FindAllString(body, -1) {
		n = strings.TrimRight(strings.ReplaceAll(n, ",", ""), ".")
		re := regexp.MustCompile(`(^|[^\d.])` + regexp.QuoteMeta(n) + `([^\d]|$)`)
		if !slices.ContainsFunc(cited, re.MatchString) {
			return false, "number " + n + " not in cited passages"
		}
	}
	return true, ""
}

func render(unit string, cites map[string]Citation) string {
	return tagRe.ReplaceAllStringFunc(unit, func(t string) string {
		c := cites[t[1:len(t)-1]]
		return fmt.Sprintf("[%s, p.%s]", shortName[c.Paper], c.Page)
	})
}

func citations(hits []retrieve.Hit) map[string]Citation {
	m := map[string]Citation{}
	for i, h := range hits {
		page := fmt.Sprint(h.Chunk.PageStart)
		if h.Chunk.PageEnd != h.Chunk.PageStart {
			page = fmt.Sprintf("%d-%d", h.Chunk.PageStart, h.Chunk.PageEnd)
		}
		sec := strings.TrimSpace(h.Chunk.SectionNumber + " " + h.Chunk.Section)
		if h.Chunk.Table != "" {
			sec += " (" + h.Chunk.Table + ")"
		}
		tag := fmt.Sprintf("S%d", i+1)
		m[tag] = Citation{Tag: tag, ChunkID: h.Chunk.ID, Paper: h.Chunk.Paper, Page: page, Section: sec}
	}
	return m
}

func listCites(cites map[string]Citation) string {
	var out []string
	for i := 1; i <= len(cites); i++ {
		c := cites[fmt.Sprintf("S%d", i)]
		out = append(out, fmt.Sprintf("%s p.%s (§%s)", shortName[c.Paper], c.Page, c.Section))
	}
	return strings.Join(out, "; ")
}

func (p *Pipeline) finishCitations(tr Trace, cites map[string]Citation) Trace {
	used := map[string]bool{}
	for _, m := range regexp.MustCompile(`\[([^\]]+), p\.([\d-]+)\]`).FindAllStringSubmatch(tr.Answer, -1) {
		used[m[1]+"|"+m[2]] = true
	}
	for i := 1; i <= len(cites); i++ {
		c := cites[fmt.Sprintf("S%d", i)]
		if used[shortName[c.Paper]+"|"+c.Page] {
			tr.Citations = append(tr.Citations, c)
		}
	}
	for _, s := range tr.Steps {
		tr.Retries += s.Retries
		tr.TokensIn += s.TokensIn
		tr.TokensOut += s.TokensOut
	}
	return tr
}

// fallback answers without the model when it cannot be reached in time or within budget:
// the person gets the most relevant passages with page references, never a guessed answer.
func (p *Pipeline) fallback(tr *Trace, err error, hits []retrieve.Hit, say func(string)) {
	cites := citations(hits)
	switch {
	case errors.Is(err, governor.ErrDailyBudget) || llm.IsDaily(err):
		tr.Status = "rate_limited"
		when := "tomorrow"
		if r := p.Gov.DailyReset(); !r.IsZero() {
			when = "at " + r.Local().Format("15:04")
		}
		say("Today's model budget is used up, so I can't write an answer now; it refills " + when + ". The passages most likely to answer this are: " + listCites(cites) + ".")
	case errors.Is(err, governor.ErrDeadlineWait):
		tr.Status = "rate_limited"
		say("The assistant is at its per-minute limit and could not answer within " + p.Cfg.Deadline.String() + ". The passages most likely to answer this are: " + listCites(cites) + ". Please ask again in a minute.")
	case errors.Is(err, context.DeadlineExceeded) || errors.Is(err, llm.ErrFirstTokenTimeout):
		tr.Status = "timeout"
		say("The model did not answer in time. The passages most likely to answer this are: " + listCites(cites) + ".")
	default:
		tr.Status = "error"
		say("The model service failed. The passages most likely to answer this are: " + listCites(cites) + ".")
	}
	tr.Err = err.Error()
	tr.Degraded = append(tr.Degraded, "passages_only")
}

func (p *Pipeline) fail(tr Trace, status string, err error) Trace {
	tr.Status, tr.Err = status, err.Error()
	return tr
}

func top(h []retrieve.Hit) float32 {
	if len(h) == 0 {
		return 0
	}
	return h[0].Score
}

func msSince(t time.Time) float64 { return float64(time.Since(t).Microseconds()) / 1000 }

func short(err error) string {
	s := err.Error()
	if len(s) > 120 {
		s = s[:120]
	}
	return s
}
// Package retrieve is the pipeline's search tool: BGE cosine top-k over the chunk index.
// Brute force: ~400 vectors x 768 dims is well under a millisecond, so no vector DB.
package retrieve

import (
	"context"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"time"

	"github.com/Praroop1435/Vaani/internal/embed"
	"github.com/Praroop1435/Vaani/internal/ingest"
)

// Setting is one retrieval configuration compared in Table 3 of the write-up.
type Setting struct {
	Name      string
	ChunkSize int // which index: data/index/chunks_<size>.json
	K         int
	Windows   bool // small-to-big: search sentence windows, return their parent chunks
}

var (
	A = Setting{Name: "A: 300 tok, k=4", ChunkSize: 300, K: 4}
	B = Setting{Name: "B: 480 tok, k=3", ChunkSize: 480, K: 3}
	C = Setting{Name: "C: 2-sentence windows -> 300 tok parents, k=4", ChunkSize: 300, K: 4, Windows: true}
)

type Index struct {
	Chunks []ingest.Chunk
	Vecs   [][]float32 // unit length, same order as Chunks
	// Optional small-to-big layer: windows_<size>.json/.f32. WinParent[i] indexes Chunks.
	WinParent []int
	WinVecs   [][]float32
}

// Load reads chunks_<size>.json and vectors_<size>.f32 written by cmd/ingest.
func Load(dir string, size int) (*Index, error) {
	js, err := os.ReadFile(fmt.Sprintf("%s/chunks_%d.json", dir, size))
	if err != nil {
		return nil, err
	}
	var chunks []ingest.Chunk
	if err := json.Unmarshal(js, &chunks); err != nil {
		return nil, err
	}
	vecs, err := readVectors(fmt.Sprintf("%s/vectors_%d.f32", dir, size), len(chunks))
	if err != nil {
		return nil, err
	}
	ix := &Index{Chunks: chunks, Vecs: vecs}
	if wjs, err := os.ReadFile(fmt.Sprintf("%s/windows_%d.json", dir, size)); err == nil {
		var ws []ingest.Window
		if err := json.Unmarshal(wjs, &ws); err != nil {
			return nil, err
		}
		if ix.WinVecs, err = readVectors(fmt.Sprintf("%s/windows_%d.f32", dir, size), len(ws)); err != nil {
			return nil, err
		}
		for _, w := range ws {
			if w.Parent < 0 || w.Parent >= len(chunks) {
				return nil, fmt.Errorf("retrieve: window parent %d out of range: re-run cmd/ingest", w.Parent)
			}
			ix.WinParent = append(ix.WinParent, w.Parent)
		}
	}
	return ix, nil
}

func readVectors(path string, n int) ([][]float32, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if want := n * embed.Dim * 4; len(raw) != want {
		return nil, fmt.Errorf("retrieve: %s has %d bytes, want %d for %d rows: re-run cmd/ingest", path, len(raw), want, n)
	}
	flat := make([]float32, n*embed.Dim)
	if _, err := binary.Decode(raw, binary.LittleEndian, flat); err != nil {
		return nil, err
	}
	vecs := make([][]float32, n)
	for i := range vecs {
		vecs[i] = flat[i*embed.Dim : (i+1)*embed.Dim]
	}
	return vecs, nil
}

type Hit struct {
	Chunk ingest.Chunk
	Score float32 // cosine similarity
}

// Search returns the k chunks most similar to q, best first.
func (ix *Index) Search(q []float32, k int) []Hit {
	hits := make([]Hit, len(ix.Chunks))
	for i, v := range ix.Vecs {
		hits[i] = Hit{ix.Chunks[i], embed.Cosine(q, v)}
	}
	sort.SliceStable(hits, func(a, b int) bool { return hits[a].Score > hits[b].Score })
	return hits[:min(k, len(hits))]
}

// SearchWindows ranks windows, keeps each parent chunk's best window score, and returns the
// top k parents. The model still sees whole chunks, so tokens per answer match setting A.
func (ix *Index) SearchWindows(q []float32, k int) []Hit {
	best := map[int]float32{}
	for i, v := range ix.WinVecs {
		p, s := ix.WinParent[i], embed.Cosine(q, v)
		if cur, ok := best[p]; !ok || s > cur {
			best[p] = s
		}
	}
	hits := make([]Hit, 0, len(best))
	for p, s := range best {
		hits = append(hits, Hit{ix.Chunks[p], s})
	}
	sort.SliceStable(hits, func(a, b int) bool {
		if hits[a].Score != hits[b].Score {
			return hits[a].Score > hits[b].Score
		}
		return hits[a].Chunk.ID < hits[b].Chunk.ID // map order is random: keep ties stable
	})
	return hits[:min(k, len(hits))]
}

// Result is what the pipeline gets back from the retrieve tool, with timings for the trace.
type Result struct {
	Hits     []Hit
	EmbedMs  float64
	SearchMs float64
}

type Retriever struct {
	Embedder *embed.Embedder
	Indexes  map[int]*Index // by chunk size
}

// Retrieve embeds the question (with BGE's query prefix) and searches the setting's index.
func (r *Retriever) Retrieve(ctx context.Context, question string, s Setting) (Result, error) {
	ix := r.Indexes[s.ChunkSize]
	if ix == nil {
		return Result{}, fmt.Errorf("retrieve: no index loaded for chunk size %d", s.ChunkSize)
	}
	t0 := time.Now()
	qv, err := r.Embedder.Embed(ctx, []string{embed.QueryPrefix + question})
	if err != nil {
		return Result{}, err
	}
	t1 := time.Now()
	var hits []Hit
	if s.Windows {
		if len(ix.WinVecs) == 0 {
			return Result{}, fmt.Errorf("retrieve: setting %q needs windows_%d.* (run cmd/ingest -windows-only)", s.Name, s.ChunkSize)
		}
		hits = ix.SearchWindows(qv[0], s.K)
	} else {
		hits = ix.Search(qv[0], s.K)
	}
	return Result{
		Hits:     hits,
		EmbedMs:  float64(t1.Sub(t0).Microseconds()) / 1000,
		SearchMs: float64(time.Since(t1).Microseconds()) / 1000,
	}, nil
}
// Command ask answers one question through the full pipeline and prints the reply as it is
// verified, then the trace (steps with waiting / working / retrying time) as JSON.
// Spends 1-3 real Groq requests unless -base points at the stand-in.
//
//	go run -tags ORT ./cmd/ask "How many attention heads does the base Transformer use?"
//	go run -tags ORT ./cmd/ask -setting C -no-understand "..."
package main

import (
	"bufio"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/Praroop1435/Vaani/internal/embed"
	"github.com/Praroop1435/Vaani/internal/governor"
	"github.com/Praroop1435/Vaani/internal/llm"
	"github.com/Praroop1435/Vaani/internal/pipeline"
	"github.com/Praroop1435/Vaani/internal/retrieve"
)

func main() {
	base := flag.String("base", llm.GroqBaseURL, "OpenAI-style endpoint (Groq, or the stand-in)")
	model := flag.String("model", "openai/gpt-oss-120b", "model id")
	setting := flag.String("setting", "A", "retrieval setting: A, B or C")
	noUnderstand := flag.Bool("no-understand", false, "skip the query-rewrite model call")
	flag.Parse()
	question := strings.Join(flag.Args(), " ")
	if question == "" {
		log.Fatal("usage: ask [flags] <question>")
	}
	key := os.Getenv("GROQ_API_KEY")
	if key == "" {
		key = envFile(".env", "GROQ_API_KEY")
	}

	ctx := context.Background()
	e, err := embed.New(ctx, embed.DefaultModelDir)
	if err != nil {
		log.Fatal(err)
	}
	defer e.Close()
	s := map[string]retrieve.Setting{"A": retrieve.A, "B": retrieve.B, "C": retrieve.C}[*setting]
	ix, err := retrieve.Load("data/index", s.ChunkSize)
	if err != nil {
		log.Fatal(err)
	}
	cfg := pipeline.Defaults
	cfg.Setting, cfg.Understand = s, !*noUnderstand
	p := &pipeline.Pipeline{
		LLM: &llm.Client{BaseURL: *base, APIKey: key, Model: *model},
		Gov: governor.New(governor.Limits{RPM: 30, TPM: 8000, RPD: 1000}), // Groq free tier, gpt-oss-120b (docs, 2026-11-09)
		Ret: &retrieve.Retriever{Embedder: e, Indexes: map[int]*retrieve.Index{s.ChunkSize: ix}},
		Cfg: cfg,
	}
	tr := p.Answer(ctx, "ask-1", question, func(piece string) { fmt.Print(piece) })
	fmt.Println()
	js, _ := json.MarshalIndent(tr, "", "  ")
	fmt.Fprintln(os.Stderr, string(js))
}

func envFile(path, name string) string {
	f, err := os.Open(path)
	if err != nil {
		return ""
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		if v, ok := strings.CutPrefix(strings.TrimSpace(sc.Text()), name+"="); ok {
			return strings.Trim(v, `"'`)
		}
	}
	return ""
}

