	for i := 0; i < 1000; i++ {
		c.Store(v0, "fp", pipeline.Trace{Question: fmt.Sprint("q", i), Status: "ok", Answer: "a", Citations: []pipeline.Citation{{Tag: "S1"}}})
	}
	const n = 20
	var embedMs, scanMs float64
	for i := 0; i < n; i++ {
