		scanMs += float64(time.Since(t1).Microseconds()) / 1000
	}
	fmt.Printf("\nLookup cost (mean of %d): embed %.1f ms + scan of 1000 entries %.2f ms\n", n, embedMs/n, scanMs/n)
	fmt.Println("wrote results/cache_eval.csv")
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

